132	/** Intervalos de atualização (ms) por classe de dado. */
133	export const TV_QUERY_INTERVALS = {
134	  /** Vendas live: polling 60s (acceptance: atualização em até 60s). */
135	  liveMs: 60_000,
136	  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
137	  slowMs: 300_000,
