235	// ─────────────────────────────────────────────────────────────────────────────
236	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
237	// ─────────────────────────────────────────────────────────────────────────────
238	
239	interface LaggedSales {
240	  lojaId: number;
241	  /** Último dia com venda registrada (YYYY-MM-DD). */
242	  dataReferencia: string;
243	  valor: number;
244	  quantidade: number;
245	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
246	  valorSemanaAnterior: number | null;
247	  /** Valor do DIA ANTERIOR ao dia de referência (dias completos), ou null. */
248	  valorDiaAnterior: number | null;
249	}
250	
251	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
252	  // 1) Último dia com dado para a loja
253	  const { data: latest, error: latestErr } = await supabase
254	    .from('historico_vendas')
255	    .select('data')
256	    .eq('loja_id', lojaId)
257	    .order('data', { ascending: false })
258	    .limit(1);
259	  if (latestErr) throw latestErr;
260	  const refDate = latest?.[0]?.data;
261	  if (!refDate) return null;
262	
263	  const weekAgoDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
264	  const dayBeforeDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -1));
265	
266	  // 2) Vendas do dia de referência + bases de comparação (dia anterior =
267	  //    comparativo PRINCIPAL v3; mesma semana = secundário)
268	  const [curRes, weekRes, dayRes] = await Promise.all([
269	    supabase
270	      .from('historico_vendas')
271	      .select('valor_total, quantidade')
272	      .eq('loja_id', lojaId)
273	      .eq('data', refDate)
274	      .limit(2000),
275	    supabase
276	      .from('historico_vendas')
277	      .select('valor_total')
278	      .eq('loja_id', lojaId)
279	      .eq('data', weekAgoDate)
280	      .limit(2000),
281	    supabase
282	      .from('historico_vendas')
283	      .select('valor_total')
284	      .eq('loja_id', lojaId)
285	      .eq('data', dayBeforeDate)
286	      .limit(2000),
287	  ]);
288	  if (curRes.error) throw curRes.error;
289	  if (weekRes.error) throw weekRes.error;
290	  if (dayRes.error) throw dayRes.error;
291	
292	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
293	  const quantidade = (curRes.data ?? []).reduce(
294	    (s, r) => s + (r.quantidade ?? 0),
295	    0,
296	  );
297	  const sumOrNull = (rows: Array<{ valor_total: number | null }> | null) => {
298	    const list = rows ?? [];
299	    return list.length > 0
300	      ? list.reduce((s, r) => s + (r.valor_total ?? 0), 0)
301	      : null;
302	  };
303	
304	  return {
305	    lojaId,
306	    dataReferencia: refDate,
307	    valor,
308	    quantidade,
309	    valorSemanaAnterior: sumOrNull(weekRes.data),
310	    valorDiaAnterior: sumOrNull(dayRes.data),
311	  };
312	}
313	
314	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
315	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
316	  return results.filter((r): r is LaggedSales => r !== null);
317	}
