319	// ─────────────────────────────────────────────────────────────────────────────
320	// Bases de comparação Degust: ONTEM (principal v3) + mesmo dia da semana
321	// passada (secundário) — uma única query em degust_vendas_diarias
322	// ─────────────────────────────────────────────────────────────────────────────
323	
324	interface DegustReferenceSales {
325	  /** R$ por loja ONTEM (base do delta principal, pró-rateada no uso). */
326	  yesterday: Map<number, number>;
327	  /** R$ por loja no MESMO DIA da semana passada (delta secundário). */
328	  lastWeek: Map<number, number>;
329	}
330	
331	async function fetchDegustReference(ctx: TvContext): Promise<DegustReferenceSales> {
332	  const yesterday = new Map<number, number>();
333	  const lastWeek = new Map<number, number>();
334	  const ids = [...ctx.degustLojaIds];
335	  if (ids.length === 0) return { yesterday, lastWeek };
336	  const now = new Date();
337	  const yesterdayDate = toIsoDateLocal(addDays(now, -1));
338	  const lastWeekDate = toIsoDateLocal(addDays(now, -7));
339	  // Paginado: degust_vendas_diarias é linha-por-produto (2 dias × N lojas
340	  // pode passar de 1000 — o PostgREST cortaria silenciosamente).
341	  const rows = await fetchAllPages((from, to) =>
342	    supabase
343	      .from('degust_vendas_diarias')
344	      .select('loja_id, valor_total, data')
345	      .in('data', [yesterdayDate, lastWeekDate])
346	      .in('loja_id', ids)
347	      .order('id')
348	      .range(from, to),
349	  );
350	  for (const row of rows) {
351	    const target = row.data === yesterdayDate ? yesterday : lastWeek;
352	    target.set(row.loja_id, (target.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
353	  }
354	  return { yesterday, lastWeek };
355	}
