363	    .from('metas_vendas')
364	    .select('loja_id, dia_semana, valor_meta')
365	    .limit(1000);
366	  if (error) throw error;
367	  const out = new Map<string, number>();
368	  for (const row of data ?? []) {
369	    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
370	  }
371	  return out;
372	}
