374	function metaFor(
375	  metas: Map<string, number> | undefined,
376	  lojaId: number,
377	  date: Date,
378	): number | null {
379	  if (!metas) return null;
380	  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
